<template>
  <div class="login-container">
    <div class="login-card">
      <h1>{{ userStore.isAuthenticated ? 'Bienvenido' : 'Ingresar' }}</h1>

      <div v-if="userStore.isAuthenticated" class="profile-section">
        <img
          v-if="userStore.picture"
          :src="userStore.picture"
          alt="Foto de perfil"
          class="profile-picture"
        />
        <div class="profile-info">
          <p class="profile-name">{{ userStore.user?.name }}</p>
          <p class="profile-email">{{ userStore.user?.email }}</p>
        </div>
        <button class="submit-btn logout-btn" @click="userStore.logout(); router.push('/')">
          Cerrar sesión
        </button>
      </div>

      <form v-else @submit.prevent="handleLogin">
        <div class="form-group">
          <label for="email">Correo Electrónico</label>
          <input
            id="email"
            v-model="email"
            type="email"
            required
            placeholder="tu@email.com"
          />
        </div>

        <div class="form-group">
          <label for="password">Contraseña</label>
          <input
            id="password"
            v-model="password"
            type="password"
            required
            placeholder="••••••••"
          />
        </div>

        <button
          type="submit"
          :disabled="userStore.isLoading"
          class="submit-btn"
        >
          {{ userStore.isLoading ? 'Cargando...' : 'Ingresar' }}
        </button>
      </form>

      <div v-if="!userStore.isAuthenticated" class="divider">
        <span>o</span>
      </div>

      <button
        v-if="!userStore.isAuthenticated"
        class="google-btn"
        @click="userStore.loginWithGoogleSupabase()"
        :disabled="userStore.isLoading"
      >
        <img src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg" alt="Logo de Google" />
        Iniciar sesión con Google
      </button>

      <div v-if="!userStore.isAuthenticated" class="signup-link">
        ¿No tienes cuenta? <router-link to="/register">Regístrate aquí</router-link>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
import { ref } from 'vue';
import { useRouter } from 'vue-router';
import { useUserStore } from '../stores/userStore';
import { useToast } from '../composables/useToast';
import { validateEmail, validatePassword } from '../utils/validators';

const email = ref('');
const password = ref('');
const userStore = useUserStore();
const router = useRouter();
const toast = useToast();

const handleLogin = async () => {
  if (!email.value || !password.value) {
    toast.error('Todos los campos son obligatorios');
    return;
  }
  if (!validateEmail(email.value)) {
    toast.error('El correo electrónico no es válido');
    return;
  }
  if (!validatePassword(password.value)) {
    toast.error('La contraseña debe tener al menos 8 caracteres');
    return;
  }

  const success = await userStore.login(email.value, password.value);
  if (success) {
    toast.success('Inicio de sesión exitoso');
    router.push('/');
  } else if (userStore.error) {
    toast.error(userStore.error);
    userStore.error = null;
  }
};
</script>

<style scoped src="@/styles/pages/login.css"></style>
